 "content": "from collections import deque


def transform(grid):
    """Fill background-color regions enclosed by the structural line color."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == bg and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == bg and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r,c) not in seen:
                out[r][c] = 4
    return out
